// Express Key Service — Day 5
//
// What this service does:
// 1. Acts as the off-chain secure custodian of AES decryption keys.
// 2. Holds the decryption keys generated by Setters in `storage/keys/<id>.key`.
// 3. Guards the key release endpoint (`POST /api/key/:paperId`):
//    - Step 1: Cryptographic challenge-response — verifies the caller really
//              owns the claimed wallet via ECDSA signature (`ethers.verifyMessage`).
//    - Step 2: On-chain contract verification — queries `ExamCustody.papers(paperId)`
//              to ensure:
//              a) Paper exists.
//              b) Paper is NOT compromised (Stage != 7).
//              c) Paper stage is KeyReleased (Stage == 5) or Opened (Stage == 6).
//              d) The verified wallet is the assigned exam centre for this paper.
// 4. Serves encrypted ciphertexts so centres can download them.
// 5. Provides a decryption helper and a public hash verification endpoint.

const express = require("express");
const cors = require("cors");
const fs = require("fs");
const path = require("path");
const { ethers } = require("ethers");
const { decrypt, hashCiphertext } = require("./cryptoUtils");

const app = express();
const PORT = process.env.PORT || 5001;

// Middleware
app.use(cors());
app.use(express.json());

// Paths
const CIPHERTEXT_DIR = path.join(__dirname, "storage", "ciphertexts");
const KEYS_DIR = path.join(__dirname, "storage", "keys");
const DEPLOYMENT_PATH = path.join(__dirname, "deployment.json");

// Solidity Stage Enum mapping for clear error messages
const STAGE_NAMES = [
  "Created",          // 0
  "Moderated",        // 1
  "PrintedSealed",    // 2
  "Dispatched",       // 3
  "ReceivedAtCentre", // 4
  "KeyReleased",      // 5
  "Opened",           // 6
  "Compromised"       // 7
];

// In-memory challenge store to prevent replay attacks
// Key: paperId:walletAddress -> { challenge, timestamp }
const activeChallenges = new Map();

// Helper: load deployment info
function getDeploymentInfo() {
  if (fs.existsSync(DEPLOYMENT_PATH)) {
    try {
      return JSON.parse(fs.readFileSync(DEPLOYMENT_PATH, "utf8"));
    } catch (err) {
      console.error("Error reading deployment.json:", err.message);
    }
  }
  return null;
}

let customContractInstance = null;

function setContractInstance(contract) {
  customContractInstance = contract;
}

// Helper: get contract instance connected to RPC provider
function getContractInstance() {
  if (customContractInstance) {
    return customContractInstance;
  }

  const deployment = getDeploymentInfo();
  if (!deployment) {
    throw new Error("deployment.json not found. Run 'npm run deploy' first.");
  }

  const rpcUrl = process.env.RPC_URL || "http://127.0.0.1:8545";
  const provider = new ethers.JsonRpcProvider(rpcUrl);
  return new ethers.Contract(deployment.contractAddress, deployment.abi, provider);
}

// ─────────────────────────────────────────
//  1. System Health & Status
// ─────────────────────────────────────────

app.get("/api/status", async (req, res) => {
  const deployment = getDeploymentInfo();
  let blockchainConnected = false;
  let contractAddress = deployment?.contractAddress || null;
  let paperCount = null;

  if (deployment) {
    try {
      const contract = getContractInstance();
      paperCount = (await contract.paperCount()).toString();
      blockchainConnected = true;
    } catch (err) {
      blockchainConnected = false;
    }
  }

  const ciphertexts = fs.existsSync(CIPHERTEXT_DIR)
    ? fs.readdirSync(CIPHERTEXT_DIR).filter(f => f.endsWith(".json")).length
    : 0;

  res.json({
    status: "online",
    service: "ExamCustody Key & Storage Service",
    port: PORT,
    blockchainConnected,
    contractAddress,
    onChainPaperCount: paperCount,
    offChainStoredPapers: ciphertexts,
    timestamp: new Date().toISOString()
  });
});

// ─────────────────────────────────────────
//  2. List All Stored Papers (Off-Chain Catalog)
// ─────────────────────────────────────────

app.get("/api/papers", (req, res) => {
  if (!fs.existsSync(CIPHERTEXT_DIR)) {
    return res.json([]);
  }

  const files = fs.readdirSync(CIPHERTEXT_DIR).filter(f => f.endsWith(".json"));
  const papers = files.map(file => {
    try {
      const data = JSON.parse(fs.readFileSync(path.join(CIPHERTEXT_DIR, file), "utf8"));
      return {
        paperId: data.paperId,
        subject: data.subject,
        ciphertextHash: data.ciphertextHash,
        fileRef: data.fileRef,
        examTime: data.examTime,
        assignedCentre: data.assignedCentre,
        createdAt: data.createdAt
      };
    } catch (e) {
      return null;
    }
  }).filter(Boolean);

  res.json(papers);
});

// ─────────────────────────────────────────
//  3. Download Ciphertext Bundle (for Centres)
// ─────────────────────────────────────────

app.get("/api/papers/:paperId/ciphertext", (req, res) => {
  const paperId = req.params.paperId;
  const filePath = path.join(CIPHERTEXT_DIR, `${paperId}.json`);

  if (!fs.existsSync(filePath)) {
    return res.status(404).json({ error: `Ciphertext for paper #${paperId} not found.` });
  }

  const data = JSON.parse(fs.readFileSync(filePath, "utf8"));
  res.json(data);
});

// ─────────────────────────────────────────
//  4. Challenge Generation (Anti-Replay)
// ─────────────────────────────────────────

app.get("/api/challenge/:paperId", (req, res) => {
  const paperId = req.params.paperId;
  const walletAddress = req.query.wallet;

  if (!walletAddress) {
    return res.status(400).json({ error: "Missing required 'wallet' query parameter." });
  }

  const nonce = Math.floor(Math.random() * 1000000);
  const timestamp = Date.now();
  const challenge = `ExamCustody Authentication Request:\nAuthorize release of AES key for Paper #${paperId}\nWallet: ${walletAddress.toLowerCase()}\nNonce: ${nonce}\nTimestamp: ${timestamp}`;

  // Store challenge valid for 5 minutes (300,000 ms)
  const mapKey = `${paperId}:${walletAddress.toLowerCase()}`;
  activeChallenges.set(mapKey, { challenge, timestamp });

  res.json({
    paperId,
    walletAddress,
    challenge,
    expiresInSeconds: 300
  });
});

// ─────────────────────────────────────────
//  5. Guarded Key Release Endpoint (Core Security)
// ─────────────────────────────────────────

app.post("/api/key/:paperId", async (req, res) => {
  const paperId = req.params.paperId;
  const { signature, walletAddress, challenge } = req.body;

  if (!signature || !walletAddress || !challenge) {
    return res.status(400).json({
      error: "Missing required fields. Provide { signature, walletAddress, challenge }."
    });
  }

  // ── STEP 1: Verify Wallet Ownership via ECDSA Signature ──
  let recoveredAddress;
  try {
    recoveredAddress = ethers.verifyMessage(challenge, signature);
  } catch (err) {
    return res.status(401).json({
      error: "Invalid cryptographic signature format.",
      details: err.message
    });
  }

  if (recoveredAddress.toLowerCase() !== walletAddress.toLowerCase()) {
    return res.status(401).json({
      error: "Signature verification failed! Recovered signer does not match provided wallet address.",
      recoveredAddress,
      providedAddress: walletAddress
    });
  }

  // ── STEP 1b: Verify Challenge Freshness & Format ──
  const mapKey = `${paperId}:${walletAddress.toLowerCase()}`;
  const storedChallenge = activeChallenges.get(mapKey);

  if (storedChallenge) {
    const age = Date.now() - storedChallenge.timestamp;
    if (age > 300000) { // older than 5 minutes
      activeChallenges.delete(mapKey);
      return res.status(401).json({ error: "Authentication challenge expired. Request a new challenge." });
    }
  }

  // ── STEP 2: Query On-Chain Contract State ──
  let contract;
  let paperOnChain;
  try {
    contract = getContractInstance();
    paperOnChain = await contract.papers(paperId);
  } catch (err) {
    return res.status(502).json({
      error: "Failed to connect to Ethereum blockchain node to verify custody status.",
      details: err.message
    });
  }

  // Check 2a: Paper must exist
  if (Number(paperOnChain.id) === 0) {
    return res.status(404).json({
      error: `Paper #${paperId} does not exist on the smart contract.`
    });
  }

  const stage = Number(paperOnChain.stage);
  const stageName = STAGE_NAMES[stage] || `Unknown (${stage})`;

  // Check 2b: Paper must NOT be compromised
  if (stage === 7) { // Stage.Compromised
    return res.status(403).json({
      error: "ACCESS DENIED: This exam paper has been flagged as COMPROMISED on-chain! Decryption keys are permanently frozen."
    });
  }

  // Check 2c: Paper must be at KeyReleased (5) or Opened (6)
  if (stage < 5) {
    return res.status(403).json({
      error: `ACCESS DENIED: Decryption key not yet released on-chain. Current stage is '${stageName}' (${stage}). Must reach 'KeyReleased' (5).`
    });
  }

  // Check 2d: Caller must be the assigned exam centre for this paper
  if (paperOnChain.centre.toLowerCase() !== walletAddress.toLowerCase()) {
    return res.status(403).json({
      error: `ACCESS DENIED: Wallet ${walletAddress} is not the designated exam centre for Paper #${paperId}.`,
      assignedCentre: paperOnChain.centre
    });
  }

  // ── STEP 3: Retrieve and Release the AES Decryption Key ──
  const keyFilePath = path.join(KEYS_DIR, `${paperId}.key`);
  if (!fs.existsSync(keyFilePath)) {
    return res.status(500).json({
      error: `Decryption key for paper #${paperId} missing from key vault.`
    });
  }

  const keyRecord = JSON.parse(fs.readFileSync(keyFilePath, "utf8"));

  // Clear challenge after successful release (one-time use)
  activeChallenges.delete(mapKey);

  console.log(`[KEY RELEASED] Released AES key for Paper #${paperId} to authenticated centre: ${walletAddress}`);

  return res.json({
    success: true,
    paperId: Number(paperId),
    keyHex: keyRecord.keyHex,
    ciphertextHash: keyRecord.ciphertextHash,
    stage: stageName,
    assignedCentre: paperOnChain.centre,
    message: "Decryption key successfully released to authenticated exam centre."
  });
});

// ─────────────────────────────────────────
//  6. Centre Decryption Helper
// ─────────────────────────────────────────

app.post("/api/papers/:paperId/decrypt", (req, res) => {
  const paperId = req.params.paperId;
  const { keyHex } = req.body;

  if (!keyHex) {
    return res.status(400).json({ error: "Missing required 'keyHex' parameter." });
  }

  const ciphertextPath = path.join(CIPHERTEXT_DIR, `${paperId}.json`);
  if (!fs.existsSync(ciphertextPath)) {
    return res.status(404).json({ error: `Ciphertext for paper #${paperId} not found.` });
  }

  try {
    const bundle = JSON.parse(fs.readFileSync(ciphertextPath, "utf8"));
    const plaintext = decrypt(bundle.ciphertext, bundle.iv, bundle.authTag, keyHex);

    res.json({
      success: true,
      paperId,
      subject: bundle.subject,
      plaintext: plaintext
    });
  } catch (err) {
    res.status(400).json({
      error: "Decryption failed! The key may be incorrect, or the ciphertext was tampered with (GCM authentication failure).",
      details: err.message
    });
  }
});

// ─────────────────────────────────────────
//  7. Public Hash Verification Endpoint
// ─────────────────────────────────────────

app.post("/api/verify-hash", async (req, res) => {
  const { paperId, ciphertext } = req.body;

  if (!paperId || !ciphertext) {
    return res.status(400).json({ error: "Provide { paperId, ciphertext } to verify." });
  }

  const calculatedHash = hashCiphertext(ciphertext);

  try {
    const contract = getContractInstance();
    const paper = await contract.papers(paperId);

    const onChainHash = paper.ciphertextHash;
    const matches = (calculatedHash.toLowerCase() === onChainHash.toLowerCase());

    res.json({
      paperId,
      calculatedHash,
      onChainHash,
      matches,
      stage: STAGE_NAMES[Number(paper.stage)] || Number(paper.stage),
      status: matches ? "VERIFIED: File matches the immutable on-chain record!" : "TAMPERED: File hash differs from blockchain record!"
    });
  } catch (err) {
    res.status(500).json({
      error: "Could not query blockchain to verify hash.",
      details: err.message
    });
  }
});

// Start listening if run directly
if (require.main === module) {
  app.listen(PORT, () => {
    console.log("════════════════════════════════════════════════════════════");
    console.log(`  ExamCustody Key Service listening on http://localhost:${PORT}`);
    console.log("════════════════════════════════════════════════════════════");
  });
}

app.setContractInstance = setContractInstance;
module.exports = app;
module.exports.setContractInstance = setContractInstance;
